static const char* b2s(bool b) { return b ? "True" : "False"; }

struct Node {
    std::shared_ptr<Node> strong;
    std::weak_ptr<Node>   weak;
    int id;
    explicit Node(int i) : id(i) { ++live; }
    ~Node() { --live; }
    static int live;
};
int Node::live = 0;

int main() {
    // ---- 反面：强引用成环 -> 泄漏 ----
    std::weak_ptr<Node> wa, wb;
    {
        auto a = std::make_shared<Node>(1);
        auto b = std::make_shared<Node>(2);
        wa = a; wb = b;
        a->strong = b;
        b->strong = a;      // 环：a 计数 2，b 计数 2
    }
    std::cout << "cycle live objects after scope=" << Node::live << "\n";
    std::cout << "cycle expired=" << b2s(wa.expired()) << "\n";
    std::cout << "cycle use_count=" << wa.use_count() << "\n";
    int liveBeforeWeak = Node::live;

    // ---- 正面：weak 断环 -> 正常释放 ----
    std::weak_ptr<Node> wa2, wb2;
    {
        auto a = std::make_shared<Node>(3);
        auto b = std::make_shared<Node>(4);
        wa2 = a; wb2 = b;
        a->weak = b;        // 用 weak 观察，不增加强计数
        b->weak = a;
        std::cout << "weak-link use_count in scope=" << wa2.use_count() << "\n";
    }
    std::cout << "after weak fix live objects=" << Node::live << "\n";
    std::cout << "weak pair fully released=" << b2s(Node::live == liveBeforeWeak) << "\n";
    std::cout << "after weak fix expired=" << b2s(wa2.expired()) << "\n";
}
